package postgres

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

func (f *fullTableModel) copySQLName() string   { return objectKey(f.m.table.Schema, f.o.CopyTable) }
func (f *fullTableModel) backupSQLName() string { return objectKey(f.m.table.Schema, f.o.BackupTable) }
func (f *fullTableModel) ownerSQL() string      { return quoteIdent(f.roles[f.e.Table.OwnerOID]) }
func (f *fullTableModel) sortedColumns() []Column {
	a := append([]Column{}, f.m.table.Columns...)
	sort.Slice(a, func(i, j int) bool { return a[i].AttNum < a[j].AttNum })
	return a
}
func (f *fullTableModel) sortedIndexes() []FullIndexFacts {
	a := append([]FullIndexFacts{}, f.e.Indexes...)
	sort.Slice(a, func(i, j int) bool { return a[i].OID < a[j].OID })
	return a
}
func (f *fullTableModel) sortedConstraints() []FullConstraint {
	a := append([]FullConstraint{}, f.e.Constraints...)
	sort.Slice(a, func(i, j int) bool { return a[i].OID < a[j].OID })
	return a
}
func (f *fullTableModel) columnType(a Column) string {
	if a.AttNum == f.m.column.AttNum {
		return f.m.vectorType()
	}
	if a.TypeOID == 1021 {
		if a.ArrayDimensions == 0 {
			return "pg_catalog._float4"
		}
		return "pg_catalog.float4" + strings.Repeat("[]", a.ArrayDimensions)
	}
	return objectKey("pg_catalog", fullScalarTypes[a.TypeOID])
}
func (f *fullTableModel) columnsSQL(keys []int) string {
	names := []string{}
	for _, a := range keys {
		names = append(names, quoteIdent(f.cols[a].Name))
	}
	return strings.Join(names, ", ")
}

func (f *fullTableModel) render(ctx context.Context) (TransitionBundle, error) {
	b := TransitionBundle{Report: f.m.r, Artifacts: []TransitionArtifact{}}
	total := 0
	add := func(name, kind, tx, content string) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		if len(content) > f.m.max-total {
			return fmt.Errorf("full-table: generated byte limit")
		}
		total += len(content)
		b.Artifacts = append(b.Artifacts, TransitionArtifact{name, kind, tx, sqlHash(content), content})
		return nil
	}
	jsonText := func(v any) string { p, _ := json.MarshalIndent(v, "", "  "); return string(p) + "\n" }
	for _, a := range []struct{ name, kind, text string }{
		{"report.json", "report", jsonText(f.m.r)},
		{"inventory.json", "evidence_only", jsonText(f.m.c)},
		{"full-table-evidence.json", "evidence_only", jsonText(f.e)},
		{"full-table-options.json", "operator_choices", jsonText(f.o)},
		{"README.md", "review_instructions", f.readme()},
	} {
		if err := add(a.name, a.kind, "none", a.text); err != nil {
			return TransitionBundle{}, err
		}
	}
	if err := add("00-preflight.sql", "read_only_reference", "independent_read_only", f.preflight()); err != nil {
		return TransitionBundle{}, err
	}
	phases := []struct {
		name string
		body func() string
	}{
		{"10-extension-transition.sql", f.m.extensionSQL},
		{"20-full-table-copy.sql", f.createCopySQL},
		{"30-verify-copy.sql", f.verifyCopySQL},
		{"40-swap-and-rebind.sql", f.swapSQL},
		{"50-verify-contracts.sql", f.contractSQL},
		{"60-application-cutover.sql", f.applicationSQL},
		{"70-rollback.sql", func() string {
			return "Before the reviewed phase-60 COMMIT, database ROLLBACK on the SAME transaction/connection reverses transactional table/extension/index/ownership changes.\nROLLBACK;\nNo sequence nextval/setval/restart is used by this plan. Independent sequence use is not rolled back; all consumers must remain quiescent.\nAfter COMMIT, the backup is a retained pre-cutover snapshot, not a current replica or automatic reverse migration. Pause writers, reconcile every new row/column/key and review dependent OIDs before any reverse swap or old-extension restore. Old hnsw availability must be re-established separately. No cleanup or reverse DDL is generated.\n"
		}},
	}
	for _, p := range phases {
		body := "BLOCKED: proposed statements withheld. Resolve blocked catalog/dependency/profile gates and regenerate.\n"
		if f.m.r.Status != "blocked" {
			body = p.body()
		}
		if err := add(p.name, "review_only_sql", "shared_offline_transaction", reviewSQL(body)); err != nil {
			return TransitionBundle{}, err
		}
	}
	sort.Slice(b.Artifacts, func(i, j int) bool { return b.Artifacts[i].Name < b.Artifacts[j].Name })
	type entry struct {
		Name        string `json:"name"`
		Kind        string `json:"kind"`
		Transaction string `json:"transaction"`
		SHA256      string `json:"sha256"`
		Bytes       int    `json:"bytes"`
	}
	entries := []entry{}
	for _, a := range b.Artifacts {
		entries = append(entries, entry{a.Name, a.Kind, a.Transaction, a.SHA256, len(a.Content)})
	}
	manifest := jsonText(struct {
		FormatVersion  int     `json:"format_version"`
		PlanSHA256     string  `json:"plan_sha256"`
		CatalogSHA256  string  `json:"catalog_sha256"`
		EvidenceSHA256 string  `json:"evidence_sha256"`
		Status         string  `json:"status"`
		MutationMode   string  `json:"mutation_mode"`
		Files          []entry `json:"files"`
	}{1, f.m.r.PlanSHA256, f.m.r.CatalogSHA256, f.evidenceHash, f.m.r.Status, "commented_review_only_never_executed", entries})
	if err := add("manifest.json", "manifest", "none", manifest); err != nil {
		return TransitionBundle{}, err
	}
	sort.Slice(b.Artifacts, func(i, j int) bool { return b.Artifacts[i].Name < b.Artifacts[j].Name })
	return b, nil
}
func (f *fullTableModel) createCopySQL() string {
	var b strings.Builder
	b.WriteString("GATES: full_table_acl_and_roles, target_capabilities, maintenance_window. Continue the SAME transaction from phase 10. All readers/writers and sequence consumers are externally quiescent.\n")
	fmt.Fprintf(&b, "SET LOCAL ROLE %s;\nSET LOCAL default_tablespace = 'pg_default';\nCREATE TABLE %s (\n", f.ownerSQL(), f.copySQLName())
	cols, values := []string{}, []string{}
	for i, a := range f.sortedColumns() {
		if i > 0 {
			b.WriteString(",\n")
		}
		fmt.Fprintf(&b, " %s %s", quoteIdent(a.Name), f.columnType(a))
		if a.TypeOID == 25 {
			b.WriteString(" COLLATE pg_catalog.\"default\"")
		}
		if a.NotNull {
			b.WriteString(" NOT NULL")
		}
		cols = append(cols, quoteIdent(a.Name))
		value := "src." + quoteIdent(a.Name)
		if a.AttNum == f.m.column.AttNum {
			value += "::" + f.m.vectorType()
		}
		values = append(values, value)
	}
	fmt.Fprintf(&b, "\n) USING heap TABLESPACE %s;\n", quoteIdent(f.e.Table.Tablespace))
	for _, a := range f.sortedColumns() {
		x := f.facts[a.AttNum]
		storage := map[string]string{"p": "PLAIN", "e": "EXTERNAL", "x": "EXTENDED", "m": "MAIN"}[x.Storage]
		fmt.Fprintf(&b, "ALTER TABLE %s ALTER COLUMN %s SET STORAGE %s;\nALTER TABLE %s ALTER COLUMN %s SET STATISTICS %d;\n", f.copySQLName(), quoteIdent(a.Name), storage, f.copySQLName(), quoteIdent(a.Name), x.Statistics)
		if x.Compression != "" {
			fmt.Fprintf(&b, "ALTER TABLE %s ALTER COLUMN %s SET COMPRESSION %s;\n", f.copySQLName(), quoteIdent(a.Name), map[string]string{"p": "pglz", "l": "lz4"}[x.Compression])
		}
	}
	// Explicit values for EVERY column avoid advancing defaults/sequences and
	// preserve ordinary arrays, NULLs and business data without SELECT * guessing.
	fmt.Fprintf(&b, "INSERT INTO %s (%s)\nSELECT %s FROM ONLY %s AS src;\n", f.copySQLName(), strings.Join(cols, ", "), strings.Join(values, ", "), f.m.tableSQL())
	b.WriteString("No defaults are evaluated during copy. Do not proceed to phase 40 until every phase-30 count/value/key check passes.\n")
	return b.String()
}
func (f *fullTableModel) verifyCopySQL() string {
	var b strings.Builder
	pk := quoteIdent(f.m.pk.Name)
	var expected int64
	for _, p := range f.m.c.Profiles {
		if p.RelationOID == f.m.table.OID && p.AttNum == f.m.column.AttNum {
			expected = p.Rows
		}
	}
	fmt.Fprintf(&b, "GATE: data_and_training. SAME transaction. Expected exhaustive source rows: %d. No query result is automatically approved.\nSELECT pg_catalog.count(*) AS copy_rows,pg_catalog.count(DISTINCT %s) AS unique_copy_keys FROM ONLY %s;\n", expected, pk, f.copySQLName())
	fmt.Fprintf(&b, "SELECT pg_catalog.count(*) FILTER (WHERE src.%s IS NULL) AS extra_keys,\n pg_catalog.count(*) FILTER (WHERE dst.%s IS NULL) AS missing_keys", pk, pk)
	sends := map[uint32]string{16: "boolsend", 17: "byteasend", 20: "int8send", 21: "int2send", 23: "int4send", 25: "textsend", 700: "float4send", 701: "float8send", 1021: "array_send"}
	for _, a := range f.sortedColumns() {
		s := "src." + quoteIdent(a.Name)
		d := "dst." + quoteIdent(a.Name)
		if a.AttNum == f.m.column.AttNum {
			d = "(" + d + ")::pg_catalog.float4[]"
		}
		fn := sends[a.TypeOID]
		fmt.Fprintf(&b, ",\n pg_catalog.count(*) FILTER (WHERE pg_catalog.%s(%s) IS DISTINCT FROM pg_catalog.%s(%s)) AS %s", fn, s, fn, d, quoteIdent(fmt.Sprintf("column_%d_binary_mismatches", a.AttNum)))
	}
	fmt.Fprintf(&b, "\nFROM ONLY %s AS src FULL JOIN ONLY %s AS dst ON src.%s=dst.%s;\n", f.m.tableSQL(), f.copySQLName(), pk, pk)
	fmt.Fprintf(&b, "SELECT pg_catalog.count(*) AS dimension_mismatches FROM ONLY %s WHERE %s IS NOT NULL AND %s(%s) IS DISTINCT FROM %d;\n", f.copySQLName(), quoteIdent(f.m.column.Name), objectKey(f.m.o.VectorSchema, "vector_dims"), quoteIdent(f.m.column.Name), f.m.o.Dimensions)
	b.WriteString("Require source count = copy count = distinct copy keys = expected count, zero missing/extra keys and zero per-column/dimension mismatches. Array binary comparison retains dimensions, lower bounds, NULL elements and finite32 component bits. Original ordinary arrays are not interpreted as vectors.\nCompare captured exact distance/norm/business fixtures and separately measure ANN recall after indexes are built. No live PostgreSQL result is included.\n")
	return b.String()
}
func (f *fullTableModel) swapSQL() string {
	var b strings.Builder
	b.WriteString("GATES: full_table_rebinding, full_table_acl_and_roles, data_and_training. SAME transaction after copy checks pass. All application sessions/cached OIDs must be retired before COMMIT.\n")
	for _, a := range f.o.ArchiveNames {
		x := f.indexes[a.IndexOID]
		fmt.Fprintf(&b, "ALTER INDEX %s RENAME TO %s;\n", objectKey(x.Schema, x.Name), quoteIdent(a.Name))
	}
	fmt.Fprintf(&b, "ALTER TABLE %s RENAME TO %s;\nALTER TABLE %s RENAME TO %s;\n", f.m.tableSQL(), quoteIdent(f.o.BackupTable), f.copySQLName(), quoteIdent(f.m.table.Name))
	for _, c := range f.sortedConstraints() {
		fmt.Fprintf(&b, "ALTER TABLE %s ADD CONSTRAINT %s ", f.m.tableSQL(), quoteIdent(c.Name))
		switch c.Kind {
		case "p":
			fmt.Fprintf(&b, "PRIMARY KEY (%s)", f.columnsSQL(c.Columns))
		case "u":
			b.WriteString("UNIQUE ")
			if f.indexFacts[c.IndexOID].NullsNotDistinct {
				b.WriteString("NULLS NOT DISTINCT ")
			}
			fmt.Fprintf(&b, "(%s)", f.columnsSQL(c.Columns))
		case "c":
			fmt.Fprintf(&b, "CHECK (%s)", f.checks[c.OID])
			if c.NoInherit {
				b.WriteString(" NO INHERIT")
			}
		}
		if c.Kind == "p" || c.Kind == "u" {
			b.WriteString(" USING INDEX TABLESPACE " + quoteIdent(f.indexFacts[c.IndexOID].Tablespace))
			if c.Deferrable {
				b.WriteString(" DEFERRABLE")
				if c.InitiallyDeferred {
					b.WriteString(" INITIALLY DEFERRED")
				} else {
					b.WriteString(" INITIALLY IMMEDIATE")
				}
			} else {
				b.WriteString(" NOT DEFERRABLE")
			}
		}
		if c.Kind == "c" && !c.Validated {
			b.WriteString(" NOT VALID")
		}
		b.WriteString(";\n")
		if c.Comment != "" {
			fmt.Fprintf(&b, "COMMENT ON CONSTRAINT %s ON %s IS %s;\n", quoteIdent(c.Name), f.m.tableSQL(), transitionLiteral(c.Comment))
		}
	}
	ann := map[uint32]bool{}
	for _, x := range f.m.indexes {
		ann[x.source.OID] = true
	}
	classes := map[uint32]OpClass{}
	for _, x := range f.m.c.OpClasses {
		classes[x.OID] = x
	}
	for _, x := range f.sortedIndexes() {
		if ann[x.OID] || x.ConstraintOID != 0 {
			continue
		}
		idx := f.indexes[x.OID]
		b.WriteString("CREATE ")
		if x.Unique {
			b.WriteString("UNIQUE ")
		}
		fmt.Fprintf(&b, "INDEX %s ON %s USING btree (", quoteIdent(idx.Name), f.m.tableSQL())
		for i, k := range x.Keys {
			if i > 0 {
				b.WriteString(", ")
			}
			fmt.Fprintf(&b, "%s %s", quoteIdent(f.cols[k.AttNum].Name), objectKey("pg_catalog", classes[idx.OpClasses[i]].Name))
			if k.Descending {
				b.WriteString(" DESC")
			} else {
				b.WriteString(" ASC")
			}
			if k.NullsFirst {
				b.WriteString(" NULLS FIRST")
			} else {
				b.WriteString(" NULLS LAST")
			}
		}
		b.WriteString(")")
		if x.NullsNotDistinct {
			b.WriteString(" NULLS NOT DISTINCT")
		}
		fmt.Fprintf(&b, " TABLESPACE %s;\n", quoteIdent(x.Tablespace))
	}
	// Reuse verified ANN parameter/profile emitter with a simple typed column.
	local := *f.m
	local.o.Approach = TypedCopyShadow
	local.o.ShadowColumn = f.m.column.Name
	b.WriteString(local.indexSQL())
	for _, a := range f.sortedColumns() {
		if def := f.defaults[a.AttNum]; def != "" {
			fmt.Fprintf(&b, "ALTER TABLE %s ALTER COLUMN %s SET DEFAULT %s;\n", f.m.tableSQL(), quoteIdent(a.Name), def)
		}
	}
	seqs := append([]FullSequence{}, f.e.Sequences...)
	sort.Slice(seqs, func(i, j int) bool { return seqs[i].OID < seqs[j].OID })
	for _, s := range seqs {
		col := quoteIdent(f.cols[s.OwnedAttNum].Name)
		fmt.Fprintf(&b, "ALTER TABLE %s ALTER COLUMN %s DROP DEFAULT;\nALTER SEQUENCE %s OWNED BY %s.%s;\n", f.backupSQLName(), col, objectKey(s.Schema, s.Name), f.m.tableSQL(), col)
	}
	fmt.Fprintf(&b, "ALTER TABLE %s OWNER TO %s;\nALTER TABLE %s REPLICA IDENTITY DEFAULT;\n", f.m.tableSQL(), f.ownerSQL(), f.m.tableSQL())
	b.WriteString(f.grantSQL())
	if f.e.Table.Comment != "" {
		fmt.Fprintf(&b, "COMMENT ON TABLE %s IS %s;\n", f.m.tableSQL(), transitionLiteral(f.e.Table.Comment))
	}
	for _, a := range f.sortedColumns() {
		if text := f.facts[a.AttNum].Comment; text != "" {
			fmt.Fprintf(&b, "COMMENT ON COLUMN %s.%s IS %s;\n", f.m.tableSQL(), quoteIdent(a.Name), transitionLiteral(text))
		}
	}
	for _, x := range f.sortedIndexes() {
		if x.Comment != "" {
			name := f.indexes[x.OID].Name
			for _, a := range f.m.indexes {
				if a.source.OID == x.OID {
					name = a.target.Name
				}
			}
			fmt.Fprintf(&b, "COMMENT ON INDEX %s IS %s;\n", objectKey(f.m.table.Schema, name), transitionLiteral(x.Comment))
		}
	}
	b.WriteString("The retained backup keeps its source data and ordinary indexes. Constraint-backed archive index renames also rename their owning constraints. Its owned-sequence defaults are deliberately removed and ownership moved to the new table; it is an archive, not a live writer. No DROP TABLE, CASCADE, sequence reset or cleanup is generated.\n")
	return b.String()
}
func (f *fullTableModel) grantSQL() string {
	var b strings.Builder
	// CREATE under the original owner can introduce current default ACLs. Clear
	// their complete captured recipient set, the original recipients and owner,
	// then rebuild exact explicit table/column grants. Owner-origin grants only.
	ids := map[uint32]bool{0: true, f.e.Table.OwnerOID: true}
	for _, list := range [][]FullGrant{f.e.Privileges, f.e.CreationPrivileges} {
		for _, g := range list {
			ids[g.GranteeOID] = true
		}
	}
	ordered := []uint32{}
	for id := range ids {
		ordered = append(ordered, id)
	}
	sort.Slice(ordered, func(i, j int) bool { return ordered[i] < ordered[j] })
	for _, id := range ordered {
		fmt.Fprintf(&b, "REVOKE ALL PRIVILEGES ON TABLE %s FROM %s;\n", f.m.tableSQL(), f.grantee(id))
	}
	grants := append([]FullGrant{}, f.e.Privileges...)
	sort.Slice(grants, func(i, j int) bool {
		a, _ := json.Marshal(grants[i])
		c, _ := json.Marshal(grants[j])
		return string(a) < string(c)
	})
	for _, g := range grants {
		p := g.Privilege
		if g.AttNum != 0 {
			p += " (" + quoteIdent(f.cols[g.AttNum].Name) + ")"
		}
		fmt.Fprintf(&b, "GRANT %s ON TABLE %s TO %s", p, f.m.tableSQL(), f.grantee(g.GranteeOID))
		if g.GrantOption {
			b.WriteString(" WITH GRANT OPTION")
		}
		b.WriteString(";\n")
	}
	return b.String()
}
func (f *fullTableModel) grantee(oid uint32) string {
	if oid == 0 {
		return "PUBLIC"
	}
	return quoteIdent(f.roles[oid])
}
func (f *fullTableModel) preflight() string {
	var b strings.Builder
	b.WriteString(f.m.preflight())
	b.WriteString("\n-- FULL-TABLE SUPPLEMENT COLLECTION REFERENCE. Still read-only. This is not a JSON collector or a completeness/authenticity proof.\n-- Recollect every declared category under owner/admin visibility and compare canonical hashes before any reviewed mutation.\nBEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;\n" + transitionLocalSettings)
	id := f.m.table.OID
	fmt.Fprintf(&b, "SELECT c.oid,c.relowner,c.relnamespace,c.reltype,t.typarray,c.reltoastrelid,c.relam,c.reltablespace,c.reloptions,c.relreplident,c.relforcerowsecurity,c.relacl,pg_catalog.obj_description(c.oid,'pg_class') AS comment\nFROM pg_catalog.pg_class AS c JOIN pg_catalog.pg_type AS t ON t.oid=c.reltype WHERE c.oid=%d;\n", id)
	fmt.Fprintf(&b, "SELECT a.attnum,a.attcollation,a.attstorage,a.attcompression,a.attstattarget,a.attoptions,a.attacl,pg_catalog.col_description(a.attrelid,a.attnum) AS comment\nFROM pg_catalog.pg_attribute AS a WHERE a.attrelid=%d AND a.attnum>0 ORDER BY a.attnum;\nSELECT ad.oid,ad.adnum,pg_catalog.pg_get_expr(ad.adbin,ad.adrelid) AS expression FROM pg_catalog.pg_attrdef AS ad WHERE ad.adrelid=%d ORDER BY ad.adnum;\n", id, id)
	fmt.Fprintf(&b, "SELECT c.oid,c.conname,c.contype,c.conkey,c.conindid,c.convalidated,c.condeferrable,c.condeferred,c.connoinherit,c.conrelid,c.confrelid,pg_catalog.pg_get_expr(c.conbin,c.conrelid) AS expression,pg_catalog.pg_get_constraintdef(c.oid) AS definition\nFROM pg_catalog.pg_constraint AS c WHERE c.conrelid=%d OR c.confrelid=%d ORDER BY c.oid;\n", id, id)
	fmt.Fprintf(&b, "SELECT i.*,c.reltablespace,c.reloptions,pg_catalog.obj_description(c.oid,'pg_class') AS comment\nFROM pg_catalog.pg_index AS i JOIN pg_catalog.pg_class AS c ON c.oid=i.indexrelid WHERE i.indrelid=%d ORDER BY i.indexrelid;\n", id)
	fmt.Fprintf(&b, "SELECT d.*,s.relowner,n.nspname,s.relname,s.relpersistence,q.*\nFROM pg_catalog.pg_depend AS d JOIN pg_catalog.pg_class AS s ON d.classid='pg_catalog.pg_class'::pg_catalog.regclass AND s.oid=d.objid AND s.relkind='S'\nJOIN pg_catalog.pg_namespace AS n ON n.oid=s.relnamespace JOIN pg_catalog.pg_sequence AS q ON q.seqrelid=s.oid\nWHERE d.refclassid='pg_catalog.pg_class'::pg_catalog.regclass AND d.refobjid=%d ORDER BY s.oid;\n", id)
	fmt.Fprintf(&b, "SELECT oid,nspname FROM pg_catalog.pg_namespace ORDER BY oid;\nSELECT oid,evtname,evtevent,evtowner,evtfoid,evtenabled,evttags FROM pg_catalog.pg_event_trigger ORDER BY oid;\nSELECT oid,rolname FROM pg_catalog.pg_roles ORDER BY oid;\nSELECT * FROM pg_catalog.pg_default_acl WHERE defaclrole=%d ORDER BY oid;\nSELECT * FROM pg_catalog.pg_shdepend WHERE classid='pg_catalog.pg_class'::pg_catalog.regclass AND objid=%d;\nSELECT * FROM pg_catalog.pg_publication_rel WHERE prrelid=%d;\nSELECT * FROM pg_catalog.pg_publication WHERE puballtables;\nSELECT * FROM pg_catalog.pg_publication_namespace WHERE pnnspid=%d;\nSELECT * FROM pg_catalog.pg_seclabel WHERE classoid='pg_catalog.pg_class'::pg_catalog.regclass AND objoid=%d;\nSELECT * FROM pg_catalog.pg_statistic_ext WHERE stxrelid=%d;\nCOMMIT;\n", f.e.Table.OwnerOID, id, id, f.e.Table.NamespaceOID, id, id)
	b.WriteString("-- Inspect transitive dependencies of the table, row types, indexes, defaults and sequences, including external consumers. Expand ACLs (including defaults) with exact grantor/grantee OIDs. Null ACL uses acldefault, not an empty grant list.\n-- Database-wide/all-table and schema publications, rules/triggers/functions/views, security labels, extended statistics, RLS and inheritance require explicit inventory; unsupported presence blocks this profile.\n")
	return b.String()
}
func (f *fullTableModel) contractSQL() string {
	var b strings.Builder
	b.WriteString("GATES: full_table_rebinding, full_table_acl_and_roles, application_cutover. SAME transaction. Compare every post-swap catalog contract to the supplement by exact schema/name/new OID. Old source OID is now the BACKUP, never the new target.\n")
	name := transitionLiteral(f.m.tableSQL())
	fmt.Fprintf(&b, "SELECT c.oid,c.relowner,c.relacl,c.relreplident,c.relam,c.reltablespace,c.reloptions,c.relrowsecurity,c.relforcerowsecurity\nFROM pg_catalog.pg_class AS c WHERE c.oid=pg_catalog.to_regclass(%s);\nSELECT a.attnum,a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attcollation,a.attstorage,a.attcompression,a.attstattarget,a.attacl,pg_catalog.pg_get_expr(d.adbin,d.adrelid) AS default_expression\nFROM pg_catalog.pg_attribute AS a LEFT JOIN pg_catalog.pg_attrdef AS d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=pg_catalog.to_regclass(%s) AND a.attnum>0 ORDER BY a.attnum;\n", name, name)
	fmt.Fprintf(&b, "SELECT oid,conname,contype,convalidated,condeferrable,condeferred,pg_catalog.pg_get_constraintdef(oid) AS definition FROM pg_catalog.pg_constraint WHERE conrelid=pg_catalog.to_regclass(%s) ORDER BY conname;\nSELECT i.indexrelid,i.indisvalid,i.indisready,i.indisunique,i.indisprimary,i.indnullsnotdistinct,pg_catalog.pg_get_indexdef(i.indexrelid) AS definition FROM pg_catalog.pg_index AS i WHERE i.indrelid=pg_catalog.to_regclass(%s) ORDER BY i.indexrelid;\n", name, name)
	for _, s := range f.e.Sequences {
		fmt.Fprintf(&b, "SELECT d.*,c.relowner,c.relacl,q.* FROM pg_catalog.pg_depend AS d JOIN pg_catalog.pg_class AS c ON c.oid=d.objid JOIN pg_catalog.pg_sequence AS q ON q.seqrelid=c.oid WHERE d.classid='pg_catalog.pg_class'::pg_catalog.regclass AND d.objid=%d;\n", s.OID)
	}
	b.WriteString(f.m.targetChecks())
	b.WriteString("Require unchanged ordinary column order/names/types/nullability/default semantics, constraints, index opclasses/order/NULLs, owner-origin ACLs/comments/storage and original sequence OIDs/options/state/ACLs. Selected vector has explicit vector(n) type. Every sequence OWNED BY must reference the NEW relation OID. Recheck dependency closure and absence inventories; do not infer success from successful DDL alone.\nMeasure actual staging ANN plans/recall and business/exact-distance fixtures. Live PostgreSQL/Neon qualification remains unperformed.\n")
	return b.String()
}
func (f *fullTableModel) applicationSQL() string {
	local := *f.m
	local.o.Approach = TypedCopyShadow
	local.o.ShadowColumn = f.m.column.Name
	// Extract only the typed query examples, not the shadow-specific commit/rollback
	// instructions. This new profile uses an explicit whole-table cutover contract.
	local.o.Mode = TransitionBatches
	text := local.applicationSQL()
	text = strings.ReplaceAll(text, "No column/table rename or app deployment is automated.", "The reviewed table swap changes relation OID; retire prepared statements/cached OIDs and reconnect all application sessions.")
	text = strings.ReplaceAll(text, "Keep source arrays current through the rollback window.", "The backup is static after COMMIT. Later writes require separately reviewed reverse reconciliation before rollback.")
	return "Only after every phase-30/50 check and every unresolved human gate is resolved, on the SAME migration connection:\nCOMMIT;\nThe following are separate post-commit application transaction examples. No deployment is performed.\n" + text
}
func (f *fullTableModel) readme() string {
	var b strings.Builder
	fmt.Fprintf(&b, "# Whole-table transition review\n\nStatus: %s. Plan `%s`. Catalog `%s`. Supplement `%s`.\n\n", f.m.r.Status, f.m.r.PlanSHA256, f.m.r.CatalogSHA256, f.evidenceHash)
	b.WriteString("This is an offline PostgreSQL 16 / embedding 0.3.6 to vector 0.8.7 text generator. No SQL has been executed, no server contacted and no gate approved. Only 00-preflight.sql is active read-only SQL; every other SQL line is commented. Do not remove comments without a separately approved operational plan. Unsupported/missing evidence withholds every proposed mutation.\n\nThe full-table supplement is a captured-fact contract, not operator approval. Hashes bind supplied bytes/identity, not authenticity or completeness on a live server. Catalog v1 and the retained-array/shadow-column APIs are unchanged.\n\n## Order and transaction\n\n1. Pause all application reads/writes, DDL and sequence consumers. Verify immutable export/backup, restoration and availability of old extension binaries. Recollect all complete inventory categories with owner visibility in the same snapshot and compare both source hashes. Arbitrary application/dynamic SQL still needs an external inventory.\n2. Review every report gate, ownership/role membership/default ACL, provider extension-install policy, target capability, disk/WAL capacity and lock/downtime budget. Full-table mode has one potentially large offline transaction; no online or multi-transaction copy/swap is supported.\n3. Phase 10 starts the shared transaction, locks the source, removes only the explicitly mapped legacy indexes and uses DROP EXTENSION RESTRICT before installing/inspecting the pinned target. Unexpected dependents mean stop, never CASCADE.\n4. Phase 20 creates an actual separate typed table as the original owner, preserves every supported ordinary column, and INSERT SELECT copies all columns explicitly. No default or sequence is evaluated. Phase 30 checks every column's binary send representation, NULLs, row/key coverage and vector dimensions against the retained source. Stop on any mismatch.\n5. Phase 40 archives original ordinary index names, renames source to the explicit backup and copy to the original name, recreates typed constraints/indexes, restores defaults/comments/ACLs, and rebinds the SAME existing sequence OIDs to the new table. Backup sequence defaults are removed so the archive is not a supported writer. Sequence options/state/owner/ACLs are retained without nextval/setval/reset.\n6. Compare phase-50 new-OID catalog facts with every supplied contract, plus staging exact-distance/business results and ANN recall/plans. Do not use the old OID to check the new target. Retire prepared statements, cached OIDs and all old application sessions; renaming alone does not rebind dependencies.\n7. Only after all checks and separate application approval, phase 60 proposes COMMIT and typed query examples. The backup becomes stale immediately on later writes. Retain it and export; any post-commit reverse migration, sequence reconciliation or old-ANN service restoration needs a new plan. No source table drop or cleanup is generated.\n\n## Supported versus blocked\n\nSupported: complete PG16 ordinary permanent heap; exact built-in scalar/real-array identities; all explicit column values; preserved NOT NULL, storage/compression/statistics/comments; bounded typed-literal and owned integer-sequence defaults; immediate primary/unique constraints, bounded scalar CHECK expressions, simple built-in btree and explicitly mapped ANN indexes; original owner, owner-origin table/column ACLs with grant options and explicit default-ACL clearing; unchanged sequence object with ownership rebound; explicitly inventoried internal row types and default TOAST storage recreated by PostgreSQL with new identities.\n\nBlocked: unsupported/missing type/default/constraint/index/ACL facts; foreign/exclusion/deferrable constraints and associated triggers; identity/generated/dropped/typmod columns; custom collations/storage options; views/materialized views/functions/user triggers/rules/RLS/policies; inheritance/partitions/publications/security labels/extended statistics; shared/external sequences; non-owner grant chains; any unmapped incoming/outgoing dependency. No raw catalog definition is interpolated into proposed SQL. All absence claims require complete inventory evidence.\n\n")
	for _, g := range f.m.r.Gates {
		fmt.Fprintf(&b, "- %s / %s: %s\n", md(g.Code), md(g.State), md(g.Requirement))
	}
	b.WriteString("\n## Sources and qualification\n\nPostgreSQL 16 CREATE/ALTER TABLE, CREATE INDEX, ALTER SEQUENCE and GRANT reference semantics; pinned extension profiles from the existing migration guide. This bundle has only synthetic Go generator/JSON/CLI qualification, not live PostgreSQL or Neon execution. No current Neon support/availability is inferred from the historical migration chapter. Restricted durability/security/release qualification remains separate.\n")
	return b.String()
}
